using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPurgedActivateActionEffect", menuName = "Data/Battle/Effects/Enemy/OnPurgedActivateAction Effect")]
public class OnPurgedActivateActionEffect : Effect
{
	private const float beforeActivatingActionDelay = 0.2f;

	[Header("Action")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private bool enableSecondBattleAction;

	[SerializeField]
	[ShowIf("enableSecondBattleAction")]
	private BattleAction secondBattleAction;

	[SerializeField]
	[ShowIf("enableSecondBattleAction")]
	private int secondBattleActionAmount;

	[Header("VFX")]
	[SerializeField]
	[ShowIf("enableVFX")]
	private float vfxDelay;

	[SerializeField]
	[ShowIf("enableVFX")]
	private float beforeVFXDelay;

	[Header("Blighted Soul")]
	[SerializeField]
	private bool blightedSoul;

	public BattleAction BattleAction => battleAction;

	public bool BlightedSoul => blightedSoul;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (amount == EffectsValues.NO_VALUE)
		{
			amount = -1;
		}
		if (enableSecondBattleAction)
		{
			string arg = Smart.Format(base.localizationManager.GetLocalizedWhenEnemyDefeatedBase(), battleAction.GetActionDescription(amount).LowercaseFirst().RemoveLast());
			DefaultEffectAction defaultEffectAction = secondBattleAction as DefaultEffectAction;
			return Smart.Format(GetLocalizedDescription(), arg, secondBattleActionAmount, defaultEffectAction.Effect.GetEffectName()) + AppendedDescription();
		}
		return Smart.Format(base.localizationManager.GetLocalizedWhenEnemyDefeatedBase(), battleAction.GetActionDescription(amount).LowercaseFirst()) + AppendedDescription();
	}

	protected override string AppendedDescription()
	{
		string text = "";
		if (blightedSoul)
		{
			text = "\n" + base.localizationManager.GetLocalizedAfterFirstCantSeeMeterBase(GetLocalizedDescription());
		}
		return base.AppendedDescription() + text;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueCompanionAndEnemyDefeatAction(ActivateEffectCoroutine(effectAmount, effectOwner));
		instance.SetActionsQueueState();
		return effectAmount;
	}

	private IEnumerator ActivateEffectCoroutine(int effectAmount, GameObject effectOwner)
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count < 1)
		{
			yield break;
		}
		yield return new WaitForSeconds(IsVFXEnabled() ? beforeVFXDelay : 0f);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		SpawnVFX(GetVFXOwnerPosition(effectOwner), 6f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		yield return new WaitForSeconds(IsVFXEnabled() ? vfxDelay : 0.2f);
		if (IsSecondVFXEnabled())
		{
			List<GameObject> actionTargets = battleAction.enemyActionLogic.GetActionTargets();
			for (int i = 0; i < actionTargets.Count; i++)
			{
				SpawnSecondVFX(GetVFXOwnerPosition(actionTargets[i]), 3f);
			}
		}
		battleAction.enemyActionLogic.ActivateAction(battleAction, effectAmount, null);
		if (!enableSecondBattleAction)
		{
			yield break;
		}
		if (IsSecondVFXEnabled())
		{
			List<GameObject> actionTargets2 = secondBattleAction.enemyActionLogic.GetActionTargets();
			for (int j = 0; j < actionTargets2.Count; j++)
			{
				SpawnSecondVFX(GetVFXOwnerPosition(actionTargets2[j]), 3f);
			}
		}
		secondBattleAction.enemyActionLogic.ActivateAction(secondBattleAction, secondBattleActionAmount, null);
	}

	public override int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
	{
		SpawnSecondVFX(GetVFXOwnerPosition(effectOwner));
		PlaySecondEffectActivationSFX();
		return effectAmount;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (blightedSoul && ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentTurnAreaTurnsBattles.Count > 0 && ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter >= 2)
		{
			effectOwner.GetComponent<CorruptedAnimalEffects>().ToggleHideCorruption(value: true);
		}
	}
}
